package com.securebiz.securitydata.service;
import com.securebiz.audit.repository.ActivityLogRepository;import com.securebiz.securitydata.repository.SecurityEventRepository;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Propagation;import org.springframework.transaction.annotation.Transactional;import java.time.*;import java.util.UUID;
@Service public class DeniedAccessRecorder{private final ActivityLogRepository audit;private final SecurityEventRepository events;public DeniedAccessRecorder(ActivityLogRepository audit,SecurityEventRepository events){this.audit=audit;this.events=events;}@Transactional(propagation=Propagation.REQUIRES_NEW)public void record(UUID user,UUID session,String uri,String method,String ip,String agent){String module=module(uri);String safeUri=uri.replaceAll("[^a-zA-Z0-9_./{}-]","_");audit.appendDenied(user,session,module,safeUri,ip,agent,"{\"method\":\""+method+"\"}");String dedup="denied:"+user+":"+method+":"+safeUri+":"+Instant.now().getEpochSecond()/60;events.create(user,"ACCESS_DENIED",module,"MEDIUM","[\"permission_denied\"]","{\"method\":\""+method+"\",\"uri\":\""+safeUri+"\"}",dedup);}private String module(String uri){String[] parts=uri.split("/");return parts.length>3?parts[3]:"unknown";}}
